// ── Colour definitions per bar ──────────────────────────────────────────────
interface BarPalette {
  dark:  number;  // gradient left (darker)
  mid:   number;  // gradient middle
  light: number;  // gradient right / highlight
}

const PAL_HP:   BarPalette = { dark: COLORS.GREEN_4, mid: COLORS.GREEN_3, light: COLORS.GREEN_1 };
const PAL_ARM:  BarPalette = paletteFromColor(ARMOR_COLOR);
const PAL_ADR:  BarPalette = { dark: COLORS.BLUE_4,  mid: COLORS.BLUE_3,  light: COLORS.BLUE_1 };
const PAL_ULT:  BarPalette = { dark: COLORS.RED_3,   mid: COLORS.RED_2,   light: COLORS.RED_1 };
const PAL_WPN:  BarPalette = { dark: COLORS.GREY_5,  mid: COLORS.GREY_4,  light: COLORS.GREY_2 };
const PAL_UTIL: BarPalette = { dark: 0x8a4018,  mid: 0xd97030,  light: 0xf0a048 };
const PAL_CAP:  BarPalette = { dark: COLORS.BROWN_5, mid: COLORS.GOLD_3, light: COLORS.GOLD_1 };

const COL_HP_TRAIL = COLORS.RED_1;
const COL_BAR_BG   = COLORS.GREY_9;
const COL_BAR_BG2  = COLORS.GREY_8;
const COL_BORDER   = COLORS.GREY_6;
const COL_DIVIDER  = COLORS.GREY_7;

// Texture key for the separate adrenaline gain burst. Bar energy uses LivingBarEffect directly.
const TEX_PARTICLE   = '_hud_particle';

export function configureArenaHudLayout(nextPanelWidth = DEFAULT_PANEL_W): void {
  panelWidth = nextPanelWidth;
  barWidth = panelWidth - PAD * 2;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

/** Derive a full BarPalette from a single base colour by shifting brightness. */
function paletteFromColor(base: number): BarPalette {
  const r = (base >> 16) & 0xff;
  const g = (base >> 8) & 0xff;
  const b = base & 0xff;
  const darken  = (v: number, f: number) => Math.max(0, Math.round(v * f));
  const lighten = (v: number, f: number) => Math.min(255, Math.round(v + (255 - v) * f));
  const toHex   = (rv: number, gv: number, bv: number) => (rv << 16) | (gv << 8) | bv;
  return {
    dark:  toHex(darken(r, 0.55), darken(g, 0.55), darken(b, 0.55)),
    mid:   base,
    light: toHex(lighten(r, 0.35), lighten(g, 0.35), lighten(b, 0.35)),
  };
}

function makeBgTexture(scene: Phaser.Scene, key: string, width: number, height: number): void {
  if (scene.textures.exists(key)) scene.textures.remove(key);
  const ct = scene.textures.createCanvas(key, width, height)!;
  const ctx = ct.context;
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, rgbStr(COL_BAR_BG2));
  grad.addColorStop(1, rgbStr(COL_BAR_BG));
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
  // Inner shadow line at top
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(0, 0, width, 1);
  ct.refresh();
}

function makeRadialTexture(scene: Phaser.Scene, key: string, size: number, colorStops: [number, string][]): void {
  if (scene.textures.exists(key)) return;
  const ct = scene.textures.createCanvas(key, size, size)!;
  const ctx = ct.context;
  const half = size / 2;
  const grad = ctx.createRadialGradient(half, half, 0, half, half, half);
  for (const [stop, color] of colorStops) grad.addColorStop(stop, color);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  ct.refresh();
}

// ── Types ───────────────────────────────────────────────────────────────────

interface BarBundle {
  layout: BarLayout;
  panelBg?:     Phaser.GameObjects.Rectangle;
  label:        Phaser.GameObjects.Text;
  bgImg:        Phaser.GameObjects.Image;
  trail?:       Phaser.GameObjects.Rectangle;
  fgImg:        Phaser.GameObjects.Image;
  // Shared GPU field; this remains visible while the bar is energized.
  idleEffect:   LivingBarEffect;
  border:       Phaser.GameObjects.Rectangle;
  valueText?:   Phaser.GameObjects.Text;
  highlight?:   Phaser.GameObjects.Rectangle;
  palette:      BarPalette;
  texKey:       string;
  prevFrac:     number;
  currentFrac:  number;
  renderedWidth: number;
  energized:    boolean;       // true = the shared living field is in its energized state
  keepAliveWhenPresentationInactive: boolean;
  energyIntensity: number;    // 0..1 – direct mapping of the former particle intensity
}

interface BarLayout {
  readonly x: number;
  readonly width: number;
  readonly height: number;
  readonly labelX: number;
  readonly labelOriginX: number;
  readonly panelWidth: number;
  readonly panelHeight: number;
  readonly totalHeight: number;
  readonly gap: number;
  readonly backgroundTextureKey: string;
  readonly centeredLabel: boolean;
  readonly fitLabel: boolean;
}

function getMainBarLayout(): BarLayout {
  return {
    x: BAR_X,
    width: barWidth,
    height: BAR_H,
    labelX: BAR_X,
    labelOriginX: 0,
    panelWidth: barWidth + 20,
    panelHeight: 38,
    totalHeight: 34,
    gap: 12,
    backgroundTextureKey: '_hud_bar_bg',
    centeredLabel: false,
    fitLabel: false,
  };
}

const POWER_UP_BAR_LAYOUT: BarLayout = {
  x: BOTTOM_STACK_BAR_LEFT,
  width: BOTTOM_STACK_BAR_W,
  height: BOTTOM_STACK_BAR_H,
  labelX: 0,
  labelOriginX: 0.5,
  panelWidth: BOTTOM_STACK_PANEL_W,
  panelHeight: BOTTOM_STACK_PANEL_H,
  totalHeight: BOTTOM_STACK_TOTAL_H,
  gap: BOTTOM_STACK_GAP,
  backgroundTextureKey: '_hud_stack_bg',
  centeredLabel: true,
  fitLabel: true,
};

/** Info about a single active power-up buff for HUD display. */
export interface ActivePowerUpInfo {
  defId:         string;
  remainingFrac: number; // 1 = full, 0 = expired
  valueText?:    string;
  intensity?:    number; // 0..1 – skaliert die Energized-Intensität der Leiste
}

/** Data pushed every frame from ArenaScene. */
export interface ArenaHUDData {
  hp:                       number;
  maxHp:                    number;
  armor:                    number;
  maxArmor:                 number;
  adrenaline:               number;
  maxAdrenaline:            number;
  rage:                     number;
  maxRage:                  number;
  isUltimateActive:         boolean;
  ultimateRequiredRage:     number;
  ultimateThresholds:       number[];
  ultimateId?:              string;
  weapon1CooldownFrac:      number;
  weapon2CooldownFrac:      number;
  utilityCooldownFrac:      number;
  utilityId?:               string;
  utilityCapacityCost?:     number;
  adrenalineSyringeActive?: boolean;
  isUtilityOverridden?:     boolean;
  activePowerUps?:          ActivePowerUpInfo[];
  shieldBuff?:              ShieldBuffHudState;
  weapon2AdrenalineCost?:   number;
  /** Nur beim Ingenieur gesetzt; `constructionCapacityMax = 0` blendet die Leiste aus. */
  constructionCapacityUsed?: number;
  constructionCapacityMax?:  number;
}

// ── Class ───────────────────────────────────────────────────────────────────

export class ArenaHUD {
  private hp!:      BarBundle;
  private armor!:   BarBundle;
  private adr!:     BarBundle;
  private ult!:     BarBundle;
  private w1!:      BarBundle;
  private w2!:      BarBundle;
  private util!:    BarBundle;
  private presentationActive = true;
  private loadoutNames = { weapon1: '', weapon2: '', utility: '', ultimate: '' };

  // Name
  private nameText!:        Phaser.GameObjects.Text;
  private nameScrollTween:  Phaser.Tweens.Tween | null = null;

  // Ultimate glow
  private ultGlow:          GlowHandle | null = null;
  private ultPulseTween:    Phaser.Tweens.Tween | null = null;
  private wasUltReady       = false;
  private ultThresholdMarks: Phaser.GameObjects.Rectangle[] = [];

  // HP catch-up
  private hpTrailDelay:     Phaser.Time.TimerEvent | null = null;
  private armorTrailDelay:  Phaser.Time.TimerEvent | null = null;

  // Adrenaline burst particles (separate from the shared bar field)
  private adrBurstEmitter:  Phaser.GameObjects.Particles.ParticleEmitter | null = null;
  private currentMaxAdrenaline = 100;
  private currentMaxRage = 600;
  private currentMaxArmor = ARMOR_MAX;

  // Adrenaline syringe state
  private adrSyringeGlow:   GlowHandle | null = null;
  private adrSyringeTween:  Phaser.Tweens.Tween | null = null;
  private wasSyringeActive  = false;
  private lastHpText: string | null = null;
  private lastArmorText: string | null = null;

  // Utility override
  private utilWobbleGlow:     GlowHandle | null = null;
  private utilWobbleTween:    Phaser.Tweens.Tween | null = null;
  private utilLabelPulseTween: Phaser.Tweens.Tween | null = null;
  private wasUtilityOverridden = false;

  private currentUtilityName = '';

  // Adrenaline tick marks (weapon2 cost indicators)
  private adrTickMarks: Phaser.GameObjects.Rectangle[] = [];
  private weapon2AdrCost = 0;
  private w2Insufficient = false;
  private w2RedOverlay!: Phaser.GameObjects.Rectangle;

  // Power-Up section
  /** Currently visible power-up bar entries (keyed by defId), using full BarBundle. */
  private puEntries = new Map<string, BarBundle>();
  /** Ordered list of currently shown defIds (for layout). */
  private puOrder: string[] = [];
  private puFadeTween: Phaser.Tweens.Tween | null = null;
  private pendingPuEntries: ActivePowerUpInfo[] | null = null;

  constructor(
    private scene: Phaser.Scene,
    private container: Phaser.GameObjects.Container,
    private puContainer: Phaser.GameObjects.Container,
  ) {
    this.ensureTextures();
    this.build();
  }

  // ── Textures ──────────────────────────────────────────────────────────────

  private ensureTextures(): void {
    const s = this.scene;
    makeBgTexture(s, '_hud_bar_bg', barWidth, BAR_H);
    makeBgTexture(s, '_hud_stack_bg', BOTTOM_STACK_BAR_W, BOTTOM_STACK_BAR_H);
    ensureLivingBarTextures(s);

    // Bar gradient textures
    createGradientTexture(s, '_hud_hp',   PAL_HP,   barWidth, BAR_H);
    createGradientTexture(s, '_hud_arm',  PAL_ARM,  barWidth, BAR_H);
    createGradientTexture(s, '_hud_adr',  PAL_ADR,  barWidth, BAR_H);
    createGradientTexture(s, '_hud_ult',  PAL_ULT,  barWidth, BAR_H);
    createGradientTexture(s, '_hud_wpn',  PAL_WPN,  barWidth, BAR_H);
    createGradientTexture(s, '_hud_util', PAL_UTIL, barWidth, BAR_H);

    // Adrenaline burst particle (16x16 radial glow)
    makeRadialTexture(s, TEX_PARTICLE, 16, [
      [0,   'rgba(255,255,255,1)'],
      [0.3, 'rgba(255,255,255,0.6)'],
      [1,   'rgba(255,255,255,0)'],
    ]);

  }

  // ── Build ─────────────────────────────────────────────────────────────────

  private build(): void {
    const c = this.container;

    // Player name (large, masked for marquee)
    this.nameText = this.scene.add.text(BAR_X, NAME_Y, '', NAME_FONT).setScrollFactor(0);
    c.add(this.nameText);

    // This HUD element needs only a rectangular crop; keep it independent of world masking.
    // because we only need simple clipping for the marquee text.
    this.nameText.setCrop(0, 0, barWidth, NAME_H);

    // Dividers
    c.add(this.divider(DIV1_Y));
    c.add(this.divider(DIV2_Y));

    // Bars
    this.hp   = this.createBar(HP_LBL_Y,  HP_BAR_Y,  t('ui.hud.hp'),        PAL_HP,   '_hud_hp',   { trail: true, value: true });
    this.armor = this.createBar(ARM_LBL_Y, ARM_BAR_Y, t('ui.hud.armor'), PAL_ARM,  '_hud_arm',  { trail: true, value: true, trailColor: ARMOR_COLOR });
    this.adr  = this.createBar(ADR_LBL_Y, ADR_BAR_Y, t('ui.hud.adrenaline'), PAL_ADR,  '_hud_adr');
    this.ult  = this.createBar(ULT_LBL_Y, ULT_BAR_Y, t('ui.loadout.ultimate'), PAL_ULT,  '_hud_ult');
    this.w1   = this.createBar(W1_LBL_Y,  W1_BAR_Y,  t('ui.loadout.weapon1'), PAL_WPN,  '_hud_wpn',  { highlight: true });
    this.w2   = this.createBar(W2_LBL_Y,  W2_BAR_Y,  t('ui.loadout.weapon2'), PAL_WPN,  '_hud_wpn',  { highlight: true });
    this.util = this.createBar(UT_LBL_Y,  UT_BAR_Y,  t('ui.loadout.utility'), PAL_UTIL, '_hud_util', { highlight: true });
    this.syncUltimateThresholdMarks([]);

    // Red overlay on weapon 2 bar — shown when adrenaline is insufficient
    this.w2RedOverlay = this.scene.add.rectangle(BAR_X, W2_BAR_Y, barWidth, BAR_H, COLORS.RED_3)
      .setOrigin(0, 0).setScrollFactor(0).setAlpha(0);
    registerGraphicsObject(this.scene, 'gameplayHud', this.w2RedOverlay);
    c.add(this.w2RedOverlay);

    // Adrenaline burst particle emitter (intense, for hit-gain + syringe)
    this.adrBurstEmitter = this.scene.add.particles(0, 0, TEX_PARTICLE, {
      speed:     { min: 15, max: 60 },
      angle:     { min: 220, max: 320 },
      scale:     { start: 0.5, end: 0 },
      alpha:     { start: 0.9, end: 0 },
      lifespan:  { min: 300, max: 600 },
      tint:      [PAL_ADR.light, PAL_ADR.mid, 0xffffff],
      blendMode: Phaser.BlendModes.ADD,
      emitting:  false,
      quantity:  16,
    }).setScrollFactor(0);
    registerParticleEmitter(this.scene, 'arenaHud', this.adrBurstEmitter);
    c.add(this.adrBurstEmitter);

    // Power-Up section: dynamisch befüllt via updatePowerUpSection(), startet leer
  }

  // ── Bar factory ───────────────────────────────────────────────────────────

  private createBar(
    labelY:    number,
    barY:      number,
    labelText: string,
    palette:   BarPalette,
    texKey:    string,
    opts?:     {
      trail?: boolean;
      value?: boolean;
      highlight?: boolean;
      trailColor?: number;
      panel?: boolean;
      keepAliveWhenPresentationInactive?: boolean;
    },
    targetContainer?: Phaser.GameObjects.Container,
    layout: BarLayout = getMainBarLayout(),
  ): BarBundle {
    const c = targetContainer ?? this.container;
    const s = this.scene;

    let panelBg: Phaser.GameObjects.Rectangle | undefined;
    if (opts?.panel) {
      panelBg = s.add.rectangle(
        layout.x + layout.width / 2,
        labelY + layout.totalHeight / 2,
        layout.panelWidth,
        layout.panelHeight,
        0x000000,
        0.35,
      )
        .setScrollFactor(0);
      c.add(panelBg);
    }

    const label = s.add.text(
      layout.labelX,
      labelY,
      labelText,
      layout.centeredLabel ? BOTTOM_STACK_LABEL_FONT : LABEL_FONT,
    )
      .setOrigin(layout.labelOriginX, 0)
      .setScrollFactor(0);
    c.add(label);

    // Background
    const bgImg = s.add.image(layout.x, barY, layout.backgroundTextureKey)
      .setOrigin(0, 0).setScrollFactor(0);
    c.add(bgImg);

    // HP trail
    let trail: Phaser.GameObjects.Rectangle | undefined;
    if (opts?.trail) {
      trail = s.add.rectangle(layout.x, barY, layout.width, layout.height, opts.trailColor ?? COL_HP_TRAIL)
        .setOrigin(0, 0).setScrollFactor(0);
      c.add(trail);
    }

    // Foreground gradient (cropped)
    const fgImg = s.add.image(layout.x, barY, texKey)
      .setOrigin(0, 0).setScrollFactor(0);
    fgImg.setCrop(0, 0, layout.width, layout.height);
    c.add(fgImg);

    // Idle breathing effect (shared LivingBarEffect)
    const idlePal: LivingBarPalette = { dark: palette.dark, mid: palette.mid, light: palette.light };
    const idleEffect = new LivingBarEffect(s, c, layout.x, barY, layout.width, layout.height, idlePal,
      { glowTarget: fgImg, scrollFactor: 0 });

    // Border
    const border = s.add.rectangle(layout.x, barY, layout.width, layout.height)
      .setOrigin(0, 0).setScrollFactor(0)
      .setStrokeStyle(1, COL_BORDER)
      .setFillStyle(0x000000, 0);
    c.add(border);

    // Value text
    let valueText: Phaser.GameObjects.Text | undefined;
    if (opts?.value) {
      valueText = s.add.text(layout.x + layout.width, labelY, '', VALUE_FONT)
        .setOrigin(1, 0).setScrollFactor(0);
      c.add(valueText);
    }

    // Fire highlight
    let highlight: Phaser.GameObjects.Rectangle | undefined;
    if (opts?.highlight) {
      highlight = s.add.rectangle(layout.x - 4, barY - 4, layout.width + 8, layout.height + 8, palette.mid, 0)
        .setOrigin(0, 0).setScrollFactor(0);
      c.add(highlight);
      c.sendToBack(highlight);
    }

    return {
      layout,
      panelBg,
      label,
      bgImg,
      trail,
      fgImg,
      idleEffect,
      border,
      valueText,
      highlight,
      palette,
      texKey,
      prevFrac: 1,
      currentFrac: 1,
      renderedWidth: layout.width,
      energized: false,
      keepAliveWhenPresentationInactive: opts?.keepAliveWhenPresentationInactive ?? false,
      energyIntensity: 0,
    };
  }

  /**
   * Map the former particle intensity directly to the shared living field (0 = base,
   * 1 = maximum). This is used for unbounded buffs such as the Negev kill streak.
   */
  private setBarEnergyIntensity(bundle: BarBundle, intensity: number): void {
    const t = Phaser.Math.Clamp(intensity, 0, 1);
    if (Math.abs(bundle.energyIntensity - t) < 0.01) return;
    bundle.energyIntensity = t;
    if (bundle.energized) bundle.idleEffect.setEnergyIntensity(t);
  }

  private divider(y: number): Phaser.GameObjects.Rectangle {
    const divider = this.scene.add.rectangle(BAR_X, y, barWidth, 1, COL_DIVIDER, 0.5)
      .setOrigin(0, 0).setScrollFactor(0);
    registerGraphicsObject(this.scene, 'gameplayHud', divider);
    return divider;
  }

  // ── Public API ────────────────────────────────────────────────────────────

  setPlayerInfo(name: string, color: number): void {
    this.nameText.setText(name);
    this.nameText.setColor(toCssColor(color));
    this.nameText.setCrop(0, 0, barWidth, NAME_H);
    this.setupNameScroll();
  }

  setLoadoutNames(weapon1: string, weapon2: string, utility: string, ultimate: string): void {
    this.loadoutNames = { weapon1, weapon2, utility, ultimate };
    this.w1.label.setText(`${t('ui.loadout.weapon1')}: ${weapon1}`);
    this.w2.label.setText(`${t('ui.loadout.weapon2')}: ${weapon2}`);
    this.util.label.setText(`${t('ui.loadout.utility')}: ${utility}`);
    this.ult.label.setText(`${t('ui.loadout.ultimate')}: ${ultimate}`);
    this.currentUtilityName = utility;
  }

  refreshLocale(): void {
    this.hp.label.setText(t('ui.hud.hp'));
    this.armor.label.setText(t('ui.hud.armor'));
    this.adr.label.setText(t('ui.hud.adrenaline'));
    this.ult.label.setText(`${t('ui.loadout.ultimate')}: ${this.loadoutNames.ultimate}`);
    this.w1.label.setText(`${t('ui.loadout.weapon1')}: ${this.loadoutNames.weapon1}`);
    this.w2.label.setText(`${t('ui.loadout.weapon2')}: ${this.loadoutNames.weapon2}`);
    this.util.label.setText(`${t('ui.loadout.utility')}: ${this.loadoutNames.utility}`);
  }

  update(data: ArenaHUDData): void {
    if (!this.presentationActive) {
      this.updatePersistentPowerUps(data);
      return;
    }

    this.currentMaxArmor = Math.max(1, data.maxArmor);
    this.currentMaxAdrenaline = Math.max(1, data.maxAdrenaline);
    this.currentMaxRage = Math.max(1, data.maxRage);
    this.updateHP(data.hp, data.maxHp);
    this.updateArmor(data.armor, this.currentMaxArmor);
    this.updateAdrenaline(data.adrenaline, this.currentMaxAdrenaline, data.adrenalineSyringeActive ?? false);
    this.updateUltimate(data.rage, this.currentMaxRage, data.ultimateRequiredRage, data.ultimateThresholds, data.isUltimateActive);
    this.updateCooldownBar(this.w1, data.weapon1CooldownFrac);
    this.updateCooldownBar(this.w2, data.weapon2CooldownFrac);
    this.updateCooldownBar(this.util, data.utilityCooldownFrac);
    if ((data.weapon2AdrenalineCost ?? 0) !== this.weapon2AdrCost) {
      this.setAdrenalinTickCost(data.weapon2AdrenalineCost ?? 0);
    }

    if (data.utilityId) {
      const utilityName = getContentDisplayName(data.utilityId, getLocale());
      const capacitySuffix = (data.utilityCapacityCost ?? 0) > 0
        ? ` · ${t('ui.hud.capacityCost', { cost: data.utilityCapacityCost ?? 0 })}`
        : '';
      const displayName = `${utilityName}${capacitySuffix}`;
      if (displayName !== this.currentUtilityName) this.onUtilityNameChanged(displayName);
    }
    this.updateUtilityOverrideVisual(data.isUtilityOverridden ?? false);
    this.updatePersistentPowerUps(data);
  }

  /** Power-ups remain visible outside the TAB panel and therefore keep receiving state updates. */
  private updatePersistentPowerUps(data: ArenaHUDData): void {
    const shieldPowerUps = data.shieldBuff?.visible
      ? [{
          defId: data.shieldBuff.defId,
          remainingFrac: data.shieldBuff.maxValue > 0 ? data.shieldBuff.value / data.shieldBuff.maxValue : 0,
          valueText: `+${data.shieldBuff.damageBonusPct}%`,
        }]
      : [];
    const capacityMax = data.constructionCapacityMax ?? 0;
    const capacityUsed = Phaser.Math.Clamp(data.constructionCapacityUsed ?? 0, 0, capacityMax);
    const constructionCapacity = capacityMax > 0
      ? [{
          defId: CONSTRUCTION_CAPACITY_HUD_ID,
          remainingFrac: capacityUsed / capacityMax,
          valueText: `${Math.round(capacityUsed)} / ${Math.round(capacityMax)}`,
        }]
      : [];
    // Die Baukapazitaet steht absichtlich zuletzt: Der Power-Up-Container wird an
    // seiner Unterkante verankert, daher bleibt diese permanente Zeile an derselben
    // Stelle und zeitlich begrenzte Power-Ups wachsen nach oben.
    this.updatePowerUpSection([
      ...shieldPowerUps,
      ...(data.activePowerUps ?? []),
      ...constructionCapacity,
    ]);
  }

  /** Fully suspends the expensive, normally hidden TAB-HUD presentation. */
  setPresentationActive(active: boolean): void {
    if (this.presentationActive === active) return;
    this.presentationActive = active;

    for (const bundle of [this.hp, this.armor, this.adr, this.ult, this.w1, this.w2, this.util]) {
      this.syncBarPresentation(bundle);
    }

    if (this.adrBurstEmitter) {
      if (active) this.adrBurstEmitter.setActive(true);
      else {
        this.adrBurstEmitter.stop();
        this.adrBurstEmitter.setActive(false);
      }
    }

    for (const tween of [
      this.nameScrollTween,
      this.ultPulseTween,
      this.adrSyringeTween,
      this.utilWobbleTween,
      this.utilLabelPulseTween,
    ]) {
      if (!tween) continue;
      if (active) tween.resume();
      else tween.pause();
    }
  }

  flashSlot(slot: 'weapon1' | 'weapon2' | 'utility'): void {
    if (!this.presentationActive) return;
    const bundle = slot === 'weapon1' ? this.w1 : slot === 'weapon2' ? this.w2 : this.util;
    if (!bundle.highlight) return;
    this.scene.tweens.killTweensOf(bundle.highlight);
    bundle.highlight.setAlpha(0.4);
    this.scene.tweens.add({
      targets: bundle.highlight,
      alpha: 0,
      duration: 350,
      ease: 'Power2',
    });
  }

  /**
   * Set weapon 2 adrenaline cost per shot. Creates tick marks on the adrenaline
   * bar showing how much each shot costs. Only shown if cost >= 5.
   */
  setAdrenalinTickCost(cost: number): void {
    // Clean up old tick marks
    for (const mark of this.adrTickMarks) mark.destroy();
    this.adrTickMarks = [];
    this.weapon2AdrCost = cost;

    if (cost < 5) return;

    // Create subtle tick marks at each cost interval
    const maxAdrenaline = Math.max(1, this.currentMaxAdrenaline);
    const steps = Math.floor(maxAdrenaline / cost);
    for (let i = 1; i <= steps; i++) {
      const frac = (i * cost) / maxAdrenaline;
      const x = BAR_X + Math.round(barWidth * frac);
      const mark = this.scene.add.rectangle(x, ADR_BAR_Y + 2, 1, BAR_H - 4, 0xffffff, 0.3)
        .setOrigin(0.5, 0).setScrollFactor(0);
      registerGraphicsObject(this.scene, 'gameplayHud', mark);
      this.container.add(mark);
      this.adrTickMarks.push(mark);
    }
  }

  reset(): void {
    this.removeUltGlow();
    this.wasUltReady = false;
    this.hp.prevFrac = 1; this.hp.currentFrac = 1;
    this.armor.prevFrac = 0; this.armor.currentFrac = 0;
    this.adr.prevFrac = 1; this.adr.currentFrac = 1;
    this.ult.prevFrac = 0; this.ult.currentFrac = 0;
    this.w1.prevFrac = 0; this.w1.currentFrac = 0;
    this.w2.prevFrac = 0; this.w2.currentFrac = 0;
    this.util.prevFrac = 0; this.util.currentFrac = 0;
    this.lastHpText = null;
    this.lastArmorText = null;
    this.hpTrailDelay?.remove();
    this.hpTrailDelay = null;
    this.armorTrailDelay?.remove();
    this.armorTrailDelay = null;
    this.removeAdrSyringe();
    this.removeUtilWobble();
    this.wasSyringeActive = false;
    this.wasUtilityOverridden = false;
    this.w2Insufficient = false;
    this.w2RedOverlay.setAlpha(0);
    for (const mark of this.adrTickMarks) mark.destroy();
    this.adrTickMarks = [];
    this.weapon2AdrCost = 0;
    // Reset all bars to idle breathing mode
    for (const b of [this.hp, this.armor, this.adr, this.ult, this.w1, this.w2, this.util]) {
      b.renderedWidth = Math.max(0, Math.round(barWidth * b.currentFrac));
      b.energized = true; // force re-apply
      this.setBarEnergized(b, false);
    }
    this.puFadeTween?.destroy();
    this.puFadeTween = null;
    this.puContainer.setVisible(false);
    this.puContainer.setAlpha(1);
    if (this.nameScrollTween) {
      this.nameScrollTween.destroy();
      this.nameScrollTween = null;
    }
    this.nameText.x = BAR_X;
    // Clear power-up entries
    this.clearPowerUpEntries();
  }

  destroy(): void {
    this.removeUltGlow();
    this.hpTrailDelay?.remove();
    this.armorTrailDelay?.remove();
    this.removeAdrSyringe();
    this.removeUtilWobble();
    for (const b of [this.hp, this.armor, this.adr, this.ult, this.w1, this.w2, this.util]) {
      b.idleEffect.destroy();
    }
    if (this.nameScrollTween) this.nameScrollTween.destroy();
    this.adrBurstEmitter?.destroy();
    this.puFadeTween?.destroy();
    this.clearPowerUpEntries();
  }

  // ── Name marquee ──────────────────────────────────────────────────────────

  private setupNameScroll(): void {
    if (this.nameScrollTween) {
      this.nameScrollTween.destroy();
      this.nameScrollTween = null;
    }
    this.nameText.x = BAR_X;

    const textWidth = this.nameText.width;
    const maxWidth = barWidth;
    if (textWidth <= maxWidth) return;

    const overflow = textWidth - maxWidth;
    this.nameScrollTween = this.scene.tweens.add({
      targets: this.nameText,
      x: BAR_X - overflow,
      duration: overflow * 30,
      ease: 'Linear',
      yoyo: true,
      hold: 1500,
      repeatDelay: 1500,
      repeat: -1,
    });
  }

  // ── HP ────────────────────────────────────────────────────────────────────

  private updateHP(hp: number, maxHp: number): void {
    const safeMaxHp = Math.max(1, maxHp);
    this.updateTrackedValueBar(this.hp, hp, safeMaxHp, this.hpTrailDelay, timer => {
      this.hpTrailDelay = timer;
    });
    const nextText = `${Math.round(hp)}/${Math.round(safeMaxHp)}`;
    if (nextText !== this.lastHpText) {
      this.hp.valueText?.setText(nextText);
      this.lastHpText = nextText;
    }
  }

  private updateArmor(armor: number, maxArmor: number): void {
    this.updateTrackedValueBar(this.armor, armor, maxArmor, this.armorTrailDelay, timer => {
      this.armorTrailDelay = timer;
    });
    const nextText = `${Math.round(armor)}/${Math.round(maxArmor)}`;
    if (nextText !== this.lastArmorText) {
      this.armor.valueText?.setText(nextText);
      this.lastArmorText = nextText;
    }
  }

  private updateTrackedValueBar(
    bundle: BarBundle,
    value: number,
    maxValue: number,
    trailDelay: Phaser.Time.TimerEvent | null,
    setTrailDelay: (timer: Phaser.Time.TimerEvent | null) => void,
  ): void {
    const frac = Math.max(0, Math.min(1, value / maxValue));
    const prev = bundle.prevFrac;

    this.setBarFrac(bundle, frac);

    if (frac < prev - 0.005) {
      trailDelay?.remove();
      setTrailDelay(this.scene.time.delayedCall(400, () => {
        this.scene.tweens.add({
          targets: bundle.trail,
          width: bundle.layout.width * frac,
          duration: 600,
          ease: 'Power2',
        });
        setTrailDelay(null);
      }));
      this.flashBorder(bundle, COLORS.RED_2);
      this.shakeBar(bundle);
    } else if (frac > prev + 0.005) {
      if (bundle.trail) bundle.trail.width = bundle.layout.width * frac;
      this.flashBar(bundle);
    }

    bundle.prevFrac = frac;
  }

  // ── Adrenaline ────────────────────────────────────────────────────────────

  private updateAdrenaline(adrenaline: number, maxAdrenaline: number, syringeActive: boolean): void {
    const frac = Math.max(0, Math.min(1, adrenaline / Math.max(1, maxAdrenaline)));
    const prev = this.adr.prevFrac;

    this.setBarFrac(this.adr, frac);

    // Intense particle burst on gain (hit reward)
    if (frac > prev + 0.01) {
      this.flashBar(this.adr);
      this.emitAdrBurst(frac);
    }

    // Syringe: energized living field + glow
    this.setBarEnergized(this.adr, syringeActive);
    if (syringeActive && !this.wasSyringeActive) {
      this.startAdrSyringe();
    } else if (!syringeActive && this.wasSyringeActive) {
      this.removeAdrSyringe();
    }
    this.wasSyringeActive = syringeActive;

    // Weapon 2 insufficient adrenaline indicator
    this.updateW2InsufficientIndicator(adrenaline);

    this.adr.prevFrac = frac;
  }

  private emitAdrBurst(frac: number): void {
    if (!this.presentationActive || !this.adrBurstEmitter) return;
    const px = BAR_X + barWidth * frac;
    const py = ADR_BAR_Y + BAR_H / 2;
    this.adrBurstEmitter.setPosition(px, py);
    this.adrBurstEmitter.explode(16);
  }

  /** Show red background on weapon 2 bar when adrenaline is too low for a single shot. */
  private updateW2InsufficientIndicator(adrenaline: number): void {
    if (this.weapon2AdrCost <= 0) return;
    const insufficient = adrenaline < this.weapon2AdrCost;
    if (insufficient === this.w2Insufficient) return;
    this.w2Insufficient = insufficient;
    if (insufficient) {
      this.scene.tweens.killTweensOf(this.w2RedOverlay);
      this.scene.tweens.add({
        targets: this.w2RedOverlay,
        alpha: 0.45,
        duration: 200,
        ease: 'Quad.easeOut',
      });
    } else {
      this.scene.tweens.killTweensOf(this.w2RedOverlay);
      this.scene.tweens.add({
        targets: this.w2RedOverlay,
        alpha: 0,
        duration: 300,
        ease: 'Quad.easeIn',
      });
    }
  }

  private startAdrSyringe(): void {
    if (this.adrSyringeGlow) return;
    this.adrSyringeGlow = addExternalGlow(this.adr.fgImg, PAL_ADR.light, 2, 0, false, 0.2, 8);
    if (!this.adrSyringeGlow) return;
    this.adrSyringeTween = this.scene.tweens.add({
      targets: this.adrSyringeGlow,
      outerStrength: 6,
      duration: 500,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut',
    });
  }

  private removeAdrSyringe(): void {
    if (this.adrSyringeTween) {
      this.adrSyringeTween.destroy();
      this.adrSyringeTween = null;
    }
    if (this.adrSyringeGlow) {
      removeExternalFx(this.adr.fgImg, this.adrSyringeGlow);
      this.adrSyringeGlow = null;
    }
  }

  // ── Ultimate ──────────────────────────────────────────────────────────────

  private updateUltimate(rage: number, maxRage: number, requiredRage: number, thresholds: number[], isActive: boolean): void {
    const safeMaxRage = Math.max(1, maxRage);
    const frac = Math.max(0, Math.min(1, rage / safeMaxRage));
    const prev = this.ult.prevFrac;
    this.setBarFrac(this.ult, frac);

    if (frac > prev + 0.01) {
      this.flashBar(this.ult);
    }

    const requiredFrac = Math.max(0, Math.min(1, requiredRage / safeMaxRage));
    void requiredFrac;
    const isReady = rage >= requiredRage || isActive;
    this.setBarEnergized(this.ult, isReady);
    if (isReady && !this.wasUltReady) this.addUltGlow();
    else if (!isReady && this.wasUltReady) this.removeUltGlow();
    this.wasUltReady = isReady;
    this.ult.prevFrac = frac;

    this.syncUltimateThresholdMarks(thresholds);
  }

  private syncUltimateThresholdMarks(thresholds: number[]): void {
    const normalized = thresholds
      .filter(value => value > 0 && value < this.currentMaxRage)
      .sort((left, right) => left - right);

    while (this.ultThresholdMarks.length < normalized.length) {
      const mark = this.scene.add.rectangle(BAR_X, ULT_BAR_Y, 1, BAR_H, COL_DIVIDER, 0.5)
        .setOrigin(0.5, 0)
        .setScrollFactor(0);
      registerGraphicsObject(this.scene, 'gameplayHud', mark);
      this.container.add(mark);
      this.ultThresholdMarks.push(mark);
    }

    while (this.ultThresholdMarks.length > normalized.length) {
      this.ultThresholdMarks.pop()?.destroy();
    }

    normalized.forEach((value, index) => {
      const frac = Phaser.Math.Clamp(value / this.currentMaxRage, 0, 1);
      const mark = this.ultThresholdMarks[index];
      mark.setVisible(true);
      mark.x = BAR_X + barWidth * frac;
    });
  }

  private addUltGlow(): void {
    if (this.ultGlow) return;
    this.ultGlow = addExternalGlow(this.ult.fgImg, 0xff3300, 4, 0, false, 0.3, 10);
    if (!this.ultGlow) return;
    this.ultPulseTween = this.scene.tweens.add({
      targets: this.ultGlow,
      outerStrength: 8,
      duration: 800,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut',
    });
  }

  private removeUltGlow(): void {
    if (this.ultPulseTween) { this.ultPulseTween.destroy(); this.ultPulseTween = null; }
    if (this.ultGlow) { removeExternalFx(this.ult.fgImg, this.ultGlow); this.ultGlow = null; }
  }

  // ── Cooldown bars ─────────────────────────────────────────────────────────

  private updateCooldownBar(bundle: BarBundle, cooldownFrac: number): void {
    const readyFrac = Math.max(0, Math.min(1, 1 - cooldownFrac));
    this.setBarFrac(bundle, readyFrac);

    if (readyFrac >= 1 && bundle.prevFrac < 0.99) {
      this.flashBar(bundle);
    }
    bundle.prevFrac = readyFrac;
  }

  // ── Utility override visual ───────────────────────────────────────────────

  private onUtilityNameChanged(newName: string): void {
    this.currentUtilityName = newName;
    this.util.label.setText(`${t('ui.loadout.utility')}: ${newName}`);
    this.scene.tweens.killTweensOf(this.util.label);
    this.util.label.setScale(1);
    this.scene.tweens.add({
      targets: this.util.label,
      scaleX: 1.12,
      scaleY: 1.12,
      duration: 120,
      yoyo: true,
      ease: 'Quad.easeOut',
    });
  }

  private updateUtilityOverrideVisual(isOverridden: boolean): void {
    this.setBarEnergized(this.util, isOverridden);
    if (isOverridden && !this.wasUtilityOverridden) this.startUtilWobble();
    else if (!isOverridden && this.wasUtilityOverridden) this.removeUtilWobble();
    this.wasUtilityOverridden = isOverridden;
  }

  private startUtilWobble(): void {
    if (this.utilWobbleGlow) return;
    this.utilWobbleGlow = addExternalGlow(this.util.fgImg, PAL_UTIL.light, 3, 0, false, 0.4, 8);
    if (this.utilWobbleGlow) {
      this.utilWobbleTween = this.scene.tweens.add({
        targets: this.utilWobbleGlow,
        outerStrength: 8,
        duration: 400,
        yoyo: true,
        repeat: -1,
        ease: 'Sine.easeInOut',
      });
    }
    this.utilLabelPulseTween = this.scene.tweens.add({
      targets: this.util.label,
      scaleX: 1.06,
      scaleY: 1.06,
      duration: 600,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut',
    });
  }

  private removeUtilWobble(): void {
    if (this.utilWobbleTween) { this.utilWobbleTween.destroy(); this.utilWobbleTween = null; }
    if (this.utilWobbleGlow) { removeExternalFx(this.util.fgImg, this.utilWobbleGlow); this.utilWobbleGlow = null; }
    if (this.utilLabelPulseTween) { this.utilLabelPulseTween.destroy(); this.utilLabelPulseTween = null; }
    this.util.label.setScale(1);
  }

  // ── Power-Up section ───────────────────────────────────────────────────

  /** Properly destroy all game objects inside a BarBundle. */
  private destroyBarBundle(b: BarBundle): void {
    b.idleEffect.destroy();
    b.panelBg?.destroy();
    b.label.destroy();
    b.bgImg.destroy();
    b.fgImg.destroy();
    b.border.destroy();
    b.trail?.destroy();
    b.valueText?.destroy();
    b.highlight?.destroy();
  }

  private clearPowerUpEntries(): void {
    for (const bundle of this.puEntries.values()) this.destroyBarBundle(bundle);
    this.puEntries.clear();
    this.puOrder = [];
  }

  private rebuildPowerUpEntries(activePowerUps: ActivePowerUpInfo[]): void {
    this.clearPowerUpEntries();

    let yOff = 0;
    for (const pu of activePowerUps) {
      const def = POWERUP_DEFS[pu.defId];
      const isConstructionCapacity = pu.defId === CONSTRUCTION_CAPACITY_HUD_ID;
      if (!def && !isConstructionCapacity) continue;

      const palette = isConstructionCapacity ? PAL_CAP : paletteFromColor(def.color);
      const texKey  = this.ensurePuTexture(pu.defId, palette);
      const labelY  = yOff;
      const barY    = yOff + BOTTOM_STACK_LABEL_H;

      const bundle = this.createBar(
        labelY,
        barY,
        isConstructionCapacity
          ? t('ui.hud.constructionCapacity')
          : t('ui.hud.powerUp', { name: getContentDisplayName(pu.defId, getLocale()) }),
        palette,
        texKey,
        isConstructionCapacity || pu.defId === 'SHIELD_OVERCHARGE' || pu.defId === 'NEGEV_KILLSTREAK'
          ? { value: true, panel: true, keepAliveWhenPresentationInactive: true }
          : { panel: true, keepAliveWhenPresentationInactive: true },
        this.puContainer,
        POWER_UP_BAR_LAYOUT,
      );
      this.fitPowerUpLabel(bundle);
      if (pu.defId === 'NEGEV_KILLSTREAK') {
        bundle.bgImg.setVisible(false);
        bundle.fgImg.setVisible(false);
        bundle.border.setVisible(false);
        bundle.trail?.setVisible(false);
        bundle.highlight?.setVisible(false);
        // Ohne Balken ist die Wertzeile frei: eine Zeile tiefer, damit sie nicht
        // mehr mit dem langen Power-Up-Namen kollidiert.
        bundle.valueText?.setPosition(
          POWER_UP_BAR_LAYOUT.x + POWER_UP_BAR_LAYOUT.width,
          barY,
        );
      }
      this.setBarEnergized(bundle, true);
      this.setBarEnergyIntensity(bundle, pu.intensity ?? 0);

      this.puEntries.set(pu.defId, bundle);
      this.puOrder.push(pu.defId);
      yOff += POWER_UP_BAR_LAYOUT.totalHeight + POWER_UP_BAR_LAYOUT.gap;
    }

    const n = this.puOrder.length;
    if (n > 0) {
      const totalH = getBottomStackHeight(n);
      this.puContainer.setData('stackHeight', totalH);
      this.puContainer.setY(GAME_HEIGHT - 20 - totalH);
      this.puContainer.setAlpha(1);
      this.puContainer.setVisible(true);
      return;
    }

    this.puContainer.setData('stackHeight', 0);
    this.puContainer.setVisible(false);
    this.puContainer.setAlpha(1);
  }

  /** Ensure the gradient texture for a power-up palette exists, create lazily. */
  private ensurePuTexture(defId: string, palette: BarPalette): string {
    const key = `_hud_pu_${defId}`;
    if (!this.scene.textures.exists(key)) {
      createGradientTexture(this.scene, key, palette, BOTTOM_STACK_BAR_W, BOTTOM_STACK_BAR_H);
    }
    return key;
  }

  /** Keep long localized labels inside the shared lower-stack panel. */
  private fitPowerUpLabel(bundle: BarBundle): void {
    if (!bundle.layout.fitLabel) return;

    bundle.label.setScale(1);
    const valueReserve = bundle.valueText && bundle.valueText.text.length > 0
      ? bundle.valueText.width + 8
      : 0;
    const availableWidth = Math.max(1, bundle.layout.panelWidth - 8 - valueReserve);
    const measuredWidth = Math.max(1, bundle.label.width);
    if (measuredWidth > availableWidth) {
      bundle.label.setScale(availableWidth / measuredWidth);
    }
  }

  private updatePowerUpSection(activePowerUps: ActivePowerUpInfo[]): void {
    const visiblePowerUps = activePowerUps.filter((powerUp) =>
      powerUp.defId === CONSTRUCTION_CAPACITY_HUD_ID || powerUp.remainingFrac > 0.001
    );
    const activeIds = new Set(visiblePowerUps.map(p => p.defId));

    // Check if the set of active IDs changed
    let setChanged = activeIds.size !== this.puOrder.length;
    if (!setChanged) {
      for (const id of this.puOrder) {
        if (!activeIds.has(id)) { setChanged = true; break; }
      }
    }

    if (setChanged) {
      this.pendingPuEntries = visiblePowerUps;
      if (!this.puFadeTween && this.puOrder.length > 0 && this.puContainer.visible) {
        this.puFadeTween = this.scene.tweens.add({
          targets: this.puContainer,
          alpha: 0,
          duration: 100,
          ease: 'Linear',
          onComplete: () => {
            this.puFadeTween = null;
            const nextEntries = this.pendingPuEntries ?? [];
            this.pendingPuEntries = null;
            this.rebuildPowerUpEntries(nextEntries);
          },
        });
        return;
      }

      this.pendingPuEntries = null;
      this.puFadeTween?.destroy();
      this.puFadeTween = null;
      this.rebuildPowerUpEntries(visiblePowerUps);
    }

    // Update fractions
    for (const pu of visiblePowerUps) {
      const bundle = this.puEntries.get(pu.defId);
      if (!bundle) continue;
      const frac = Math.max(0, Math.min(1, pu.remainingFrac));
      if (pu.defId !== 'NEGEV_KILLSTREAK') this.setBarFrac(bundle, frac);
      bundle.valueText?.setText(pu.valueText ?? '');
      this.fitPowerUpLabel(bundle);
      this.setBarEnergyIntensity(bundle, pu.intensity ?? 0);
    }
  }

  // ── Bar intensity mode ──────────────────────────────────────────────────

  /** Toggle the shared living field's energized presentation for a bar. */
  private setBarEnergized(bundle: BarBundle, energized: boolean): void {
    if (bundle.energized === energized) return;
    bundle.energized = energized;
    bundle.energyIntensity = energized ? 1 : 0;
    bundle.idleEffect.setEnergyIntensity(bundle.energyIntensity);
    this.syncBarPresentation(bundle);
  }

  private syncBarPresentation(bundle: BarBundle): void {
    const hasFill = bundle.currentFrac > 0.03;
    const presentationActive = this.presentationActive || bundle.keepAliveWhenPresentationInactive;
    if (!presentationActive) {
      bundle.idleEffect.stop();
      return;
    }

    // The LivingBarEffect is always the complete presentation. Energized only changes its
    // intensity, so readiness/buffs cannot hide the living field.
    if (hasFill) bundle.idleEffect.start();
    else bundle.idleEffect.stop();
  }

  // ── Shared bar helpers ────────────────────────────────────────────────────

  /** Set the visible fill fraction; the shared living field is cropped to the filled area. */
  private setBarFrac(bundle: BarBundle, frac: number): void {
    const w = Math.max(0, Math.round(bundle.layout.width * frac));
    if (bundle.renderedWidth === w && Math.abs(bundle.currentFrac - frac) < 0.0001) return;

    bundle.fgImg.setCrop(0, 0, w, bundle.layout.height);
    bundle.currentFrac = frac;
    bundle.renderedWidth = w;

    // Update idle effect zone
    bundle.idleEffect.setFilledWidth(w);

    // The shared living field owns both the base and energized presentation.
    this.syncBarPresentation(bundle);
  }

  /** Quick flash effect on bar (border highlight). */
  private flashBar(bundle: BarBundle): void {
    bundle.border.setStrokeStyle(2, bundle.palette.light);
    this.scene.tweens.add({
      targets: bundle.border,
      alpha: { from: 1, to: 0.6 },
      duration: 150,
      yoyo: true,
      onComplete: () => {
        bundle.border.setStrokeStyle(1, COL_BORDER);
        bundle.border.setAlpha(1);
      },
    });
  }

  /** Flash border with a specific color (damage). */
  private flashBorder(bundle: BarBundle, flashColor: number): void {
    bundle.border.setStrokeStyle(2, flashColor);
    this.scene.tweens.add({
      targets: bundle.border,
      alpha: { from: 1, to: 0.5 },
      duration: 100,
      yoyo: true,
      onComplete: () => {
        bundle.border.setStrokeStyle(1, COL_BORDER);
        bundle.border.setAlpha(1);
      },
    });
  }

  /** Shake bar elements horizontally. */
  private shakeBar(bundle: BarBundle): void {
    const targets = [bundle.bgImg, bundle.fgImg, bundle.border, bundle.trail].filter(Boolean);
    const origX = bundle.layout.x;
    this.scene.tweens.add({
      targets,
      x: origX + 3,
      duration: 40,
      yoyo: true,
      repeat: 2,
      ease: 'Linear',
      onComplete: () => {
        for (const t of targets) (t as any).x = origX;
      },
    });
  }
}
